/* PROBE core — deterministic project operations; no network requests. */
import {validateAdvisoryProject} from './advisories.js';
import {validateSavedProfiles} from './ip.js';
import {validateInvestigation} from './investigation.js';
import {validateBench} from './qualification.js';
import {CAPTURE_FORMAT,validateCapture,serialOptions,captureStats} from './serial.js';
export const VERSION='1.8.0-rc.1';
export const uid=(p='id')=>`${p}_${Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')}`;
export const now=()=>new Date().toISOString();
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function newProject(title='Untitled assessment',device='Device under test',scope=''){
 const d={id:uid('dev'),name:device,model:'',hw:'',firmware:'',notes:'',photo:''};
 return {app:'PROBE',schema:1,version:VERSION,id:uid('project'),title,scope,createdAt:now(),updatedAt:now(),deviceId:d.id,devices:[d],interfaces:[],connections:[],sessions:[],artifacts:[],components:[],advisories:[],advisoryReviews:[],services:[],networkScans:[],scanProfiles:[],debugSessions:[],benchRuns:[],investigationContexts:[],investigationBundles:[],tests:[],evidence:[],findings:[],assumptions:[],baselines:[]};
}
export const ARRAYS=['devices','interfaces','connections','sessions','artifacts','components','services','tests','evidence','findings','assumptions','baselines'];
export function validateProject(p){
 if(!p||p.app!=='PROBE'||p.schema!==1)throw Error('Choose a PROBE schema 1 project JSON file.');
 if(p.benchRuns===undefined)p.benchRuns=[];
 if(!Array.isArray(p.benchRuns)||p.benchRuns.length>100)throw Error('Invalid bench history.');
 if(p.debugSessions===undefined)p.debugSessions=[];
 if(!Array.isArray(p.debugSessions)||p.debugSessions.length>100)throw Error('Invalid debugger snapshots.');
 if(p.networkScans===undefined)p.networkScans=[];
 if(!Array.isArray(p.networkScans)||p.networkScans.length>100)throw Error('Invalid scan history.');
 if(typeof p.title!=='string'||typeof p.id!=='string')throw Error('The project identity or title is missing.');
 for(const k of ARRAYS){if(!Array.isArray(p[k]))throw Error(`Project is missing its ${k} collection.`);if(p[k].length>20000)throw Error(`${k} exceeds the supported record limit.`);}
 if(!p.devices.length)throw Error('The project must contain a device.');
 const ids=new Set(); for(const k of ARRAYS)for(const item of p[k]){if(!item||typeof item!=='object'||typeof item.id!=='string'||! /^[a-z0-9_-]+$/i.test(item.id)||ids.has(item.id))throw Error(`Invalid or duplicate identity in ${k}.`);ids.add(item.id);}
 const devs=new Set(p.devices.map(x=>x.id));if(!devs.has(p.deviceId))throw Error('Selected device is missing.');
 for(const k of ARRAYS.filter(k=>!['devices','baselines'].includes(k)))for(const x of p[k])if(!devs.has(x.deviceId))throw Error(`Unknown device reference in ${k}.`);
 const ev=new Set(p.evidence.map(x=>x.id));for(const k of ['findings','tests'])for(const x of p[k]){if(!Array.isArray(x.evidenceIds)||x.evidenceIds.some(id=>!ev.has(id)))throw Error(`Broken evidence reference in ${k}.`);}
 let captureBytes=0;for(const x of p.sessions){if(!Array.isArray(x.lines)||!Array.isArray(x.events))throw Error('Invalid serial session.');if(x.captureFormat){validateCapture(x);captureBytes+=captureStats(x).total;}}
 if(captureBytes>16*1024*1024)throw Error('Project serial captures exceed 16 MiB.');
 for(const d of p.devices){if(d.serialProfile)serialOptions(d.serialProfile);if(d.serialHistory&&(!Array.isArray(d.serialHistory)||d.serialHistory.length>20||d.serialHistory.some(h=>!h||typeof h.value!=='string'||h.value.length>16384||!['text','hex'].includes(h.mode)||!['none','LF','CR','CRLF'].includes(h.ending))))throw Error('Invalid serial command history.');}
 for(const x of p.baselines)if(!x.snapshot||typeof x.snapshot!=='object')throw Error('Invalid baseline snapshot.');
 for(const d of p.devices){if(typeof d.name!=='string')throw Error('Invalid device name.');if(d.photo&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(d.photo))throw Error('Invalid board photograph.');}
 for(const e of p.evidence){if(!Number.isSafeInteger(e.size)||e.size<0||e.size>32*1024*1024)throw Error('Invalid evidence size.');if(typeof e.title!=='string'||typeof e.data!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/=]*$/.test(e.data))throw Error('Invalid evidence payload.');if(typeof e.hash!=='string'||! /^[a-f0-9]{64}$/i.test(e.hash))throw Error('Invalid evidence hash.');}
 for(const a of p.artifacts)if(!Array.isArray(a.strings)||typeof a.entropy!=='number'||a.strings.some(s=>typeof s!=='string'))throw Error('Invalid firmware analysis.');
 for(const i of p.interfaces)if(!Number.isFinite(i.x)||!Number.isFinite(i.y)||i.x<0||i.x>100||i.y<0||i.y>100)throw Error('Invalid interface coordinates.');
 for(const s of p.sessions)if(s.lines.some(l=>typeof l.text!=='string'||typeof l.t!=='string')||s.events.some(e=>typeof e.text!=='string'))throw Error('Invalid session content.');
 for(const r of p.networkScans){if(!r||typeof r.id!=='string'||! /^[a-z0-9_-]+$/i.test(r.id)||!devs.has(r.deviceId)||!ev.has(r.evidenceId)||!ev.has(r.xmlEvidenceId)||typeof r.label!=='string'||typeof r.startedAt!=='string'||!r.profile||!Array.isArray(r.profile.targets)||!Array.isArray(r.profile.ports)||!Array.isArray(r.observations)||r.observations.length>4096)throw Error('Invalid scan history or evidence reference.');}
 for(const r of p.networkScans){if(r.profile.mode!==undefined&&!['tcp','udp','discovery'].includes(r.profile.mode))throw Error('Invalid scan mode.');if(r.hostObservations!==undefined&&(!Array.isArray(r.hostObservations)||r.hostObservations.length>64||r.hostObservations.some(h=>typeof h.host!=='string'||typeof h.state!=='string')))throw Error('Invalid host observations.');}
 for(const r of p.benchRuns){if(!r||typeof r.id!=='string'||!devs.has(r.deviceId)||!p.evidence.some(e=>e.id===r.evidenceId&&e.deviceId===r.deviceId)||!Array.isArray(r.evidenceIds)||r.evidenceIds.some(id=>!p.evidence.some(e=>e.id===id&&e.deviceId===r.deviceId)))throw Error('Invalid bench evidence reference.');validateBench(r.record);}
 for(const r of p.debugSessions)if(!r||typeof r.id!=='string'||!devs.has(r.deviceId)||!ev.has(r.evidenceId)||!Array.isArray(r.dumpEvidenceIds)||r.dumpEvidenceIds.some(id=>!ev.has(id))||typeof r.label!=='string')throw Error('Invalid debugger snapshot reference.');
 for(const a of p.artifacts){if(a.extractionEvidenceId&&!ev.has(a.extractionEvidenceId))throw Error('Missing extraction evidence.');if(a.analysisVersion===2&&(!Array.isArray(a.bins)||a.bins.length>512||!Array.isArray(a.stringRecords)||a.stringRecords.length>5000||!Array.isArray(a.headers)||a.headers.length>1024||!Array.isArray(a.review)))throw Error('Invalid firmware analysis record.');if(a.analysisVersion===2){const offset=n=>Number.isInteger(n)&&n>=0&&n<a.size;if(!Number.isInteger(a.size)||a.size<0||a.size>32*1024*1024||a.stringRecords.some(r=>!r||!offset(r.offset)||typeof r.text!=='string'||r.text.length>512)||a.bins.some(b=>!b||!offset(b.offset)||!Number.isFinite(b.entropy)||b.entropy<0||b.entropy>8)||a.headers.some(h=>!h||!offset(h.offset)||typeof h.kind!=='string')||a.review.length>15000||a.review.some(r=>!r||!offset(r.offset)||typeof r.kind!=='string'))throw Error('Invalid firmware analysis offsets or values.');}}
 if(p.evidence.reduce((n,e)=>n+(e.size||0),0)>128*1024*1024)throw Error('Project evidence exceeds 128 MiB.');
 for(const e of p.evidence)if(e.provenance){const r=e.provenance,source=p.evidence.find(x=>x.id===r.sourceEvidenceId&&x.deviceId===e.deviceId),manifest=p.evidence.find(x=>x.id===r.manifestEvidenceId&&x.deviceId===e.deviceId);if(!source||!manifest||source.hash!==r.sourceHash||manifest.hash!==r.manifestHash||e.hash!==r.fileHash)throw Error('Broken extraction provenance.');let data;try{data=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(manifest.data.split(',')[1]),c=>c.charCodeAt(0))));}catch{throw Error('Invalid provenance manifest.');}if(data.sourceHash!==source.hash||!Array.isArray(data.files)||!data.files.some(f=>f.path===r.path&&f.sha256===e.hash&&f.size===e.size))throw Error('Extracted child does not match its manifest.');}
 validateInvestigation(p);validateSavedProfiles(p);validateAdvisoryProject(p);
 return p;
}
export async function sha256(bytes){if(crypto.subtle)return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');return sha256Portable(new Uint8Array(bytes));}
export function sha256Portable(bytes){
 const k=new Uint32Array([0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2]);
 const h=new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);const n=Math.ceil((bytes.length+9)/64)*64,pad=new Uint8Array(n);pad.set(bytes);pad[bytes.length]=128;const dv=new DataView(pad.buffer);dv.setUint32(n-8,Math.floor(bytes.length/0x20000000));dv.setUint32(n-4,(bytes.length*8)>>>0);const w=new Uint32Array(64),r=(x,n)=>(x>>>n)|(x<<(32-n));
 for(let o=0;o<n;o+=64){for(let i=0;i<16;i++)w[i]=dv.getUint32(o+i*4);for(let i=16;i<64;i++){let x=w[i-15],y=w[i-2];w[i]=((r(x,7)^r(x,18)^(x>>>3))+w[i-16]+(r(y,17)^r(y,19)^(y>>>10))+w[i-7])>>>0;}let [a,b,c,d,e,f,g,z]=h;for(let i=0;i<64;i++){const t1=(z+(r(e,6)^r(e,11)^r(e,25))+((e&f)^(~e&g))+k[i]+w[i])>>>0,t2=((r(a,2)^r(a,13)^r(a,22))+((a&b)^(a&c)^(b&c)))>>>0;z=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}[a,b,c,d,e,f,g,z].forEach((x,i)=>h[i]=(h[i]+x)>>>0);}return Array.from(h,x=>x.toString(16).padStart(8,'0')).join('');
}
export function analyzeBytes(bytes){
 const counts=new Uint32Array(256);let strings=[],s='';for(const b of bytes){counts[b]++;if(b>=32&&b<=126){if(s.length<512)s+=String.fromCharCode(b);}else{if(s.length>=6&&strings.length<3000)strings.push(s);s='';}}
 if(s.length>=6&&strings.length<3000)strings.push(s);let entropy=0;for(const n of counts)if(n){let p=n/bytes.length;entropy-=p*Math.log2(p);}
 const magic=Array.from(bytes.slice(0,4)).map(x=>x.toString(16).padStart(2,'0')).join('');
 const kind=magic==='7f454c46'?'ELF executable':magic.startsWith('504b0304')?'ZIP archive':magic.startsWith('1f8b')?'gzip stream':magic==='89504e47'?'PNG image':'Unrecognized / raw binary';
 return {size:bytes.length,entropy:Number(entropy.toFixed(3)),kind,strings:[...new Set(strings)],stringLimit:strings.length>=3000};
}
export function snapshot(p,deviceId=p.deviceId){
 const select=k=>p[k].filter(x=>x.deviceId===deviceId);
 return {deviceId,device:structuredClone(p.devices.find(x=>x.id===deviceId)),interfaces:structuredClone(select('interfaces')),services:structuredClone(select('services')),artifacts:select('artifacts').map(({id,name,hash,size})=>({id,name,hash,size})),findings:select('findings').map(({id,title,severity,status,confidence})=>({id,title,severity,status,confidence})),tests:select('tests').map(({id,testId,status})=>({id,testId,status}))};
}
export function compareSnapshots(before,after){
 const changes=[];if(before.deviceId!==after.deviceId)throw Error('Compare baselines for the same device.');
 const groups=[['interfaces',x=>x.id,['label','type','status','pins','voltage']],['services',x=>`${x.host}:${x.protocol}:${x.port}`,['name','version','state']],['artifacts',x=>x.name,['hash','size']],['findings',x=>x.id,['title','severity','status','confidence']],['tests',x=>x.testId,['status']]];
 for(const [group,key,fields] of groups){const a=new Map((before[group]||[]).map(x=>[key(x),x])),b=new Map((after[group]||[]).map(x=>[key(x),x]));for(const [k,x] of b){if(!a.has(k))changes.push({group,change:'Added',label:x.label||x.title||x.name||k,detail:''});else{const old=a.get(k);for(const f of fields)if(String(old[f]??'')!==String(x[f]??''))changes.push({group,change:'Changed',label:x.label||x.title||x.name||k,detail:`${f}: ${old[f]??'—'} → ${x[f]??'—'}`});}}
 for(const [k,x] of a)if(!b.has(k))changes.push({group,change:'Removed',label:x.label||x.title||x.name||k,detail:''});}
 for(const f of ['firmware','hw','model'])if(before.device?.[f]!==after.device?.[f])changes.push({group:'device',change:'Changed',label:f,detail:`${before.device?.[f]||'—'} → ${after.device?.[f]||'—'}`});
 return changes;
}
export function mergeServices(current,incoming,deviceId,evidenceId){
 const next=structuredClone(current);for(const row of incoming){const found=next.find(x=>x.deviceId===deviceId&&x.host===row.host&&x.port===row.port&&x.protocol===row.protocol);if(found)Object.assign(found,row,{evidenceId});else next.push({...row,id:uid('svc'),deviceId,evidenceId});}return next;
}
function componentMeta(c,spdx=false){const pairs={supplier:spdx?c.supplier:c.supplier?.name,group:c.group,publisher:c.publisher,sourceRef:spdx?c.SPDXID:c['bom-ref'],ecosystem:c.ecosystem};return Object.fromEntries(Object.entries(pairs).filter(([,v])=>typeof v==='string'&&v).map(([k,v])=>[k,v.slice(0,2048)]));}
export function parseSbom(obj){
 if(obj.bomFormat==='CycloneDX'&&Array.isArray(obj.components))return obj.components.map(c=>({...componentMeta(c),name:String(c.name||'Unknown'),version:String(c.version||''),purl:String(c.purl||''),license:(c.licenses||[]).map(l=>l.license?.id||l.license?.name||l.expression||'').join(', ')}));
 if(obj.spdxVersion&&Array.isArray(obj.packages))return obj.packages.map(c=>({...componentMeta(c,true),name:String(c.name||'Unknown'),version:String(c.versionInfo||''),purl:(c.externalRefs||[]).find(r=>r.referenceType==='purl')?.referenceLocator||'',license:String(c.licenseConcluded||c.licenseDeclared||'')}));
 throw Error('Choose a CycloneDX JSON or SPDX JSON software bill of materials.');
}
export const TESTS=[
 {id:'scope',area:'Boundary',title:'Confirm the assessment boundary',why:'Make the environment and permitted interfaces explicit.',steps:'Identify device model, hardware and firmware revisions. Record included interfaces, accounts, services, access level and excluded systems. Record the test environment and any operational constraints.',expected:'A reproducible scope and identified device configuration.'},
 {id:'debug',area:'Boundary',title:'Inspect debug interface exposure',why:'Determine whether service or debug connections expose unintended access.',steps:'Identify candidate connectors. Record measured voltage and pin assignments before connection. Observe available functionality and any authentication requirement. Record access level and whether access persists on production firmware.',expected:'Debug access is consistent with the product threat model and its required physical protections.'},
 {id:'boot',area:'Boottrace',title:'Review startup information disclosure',why:'Startup output may reveal sensitive configuration or access.',steps:'Capture a complete startup session. Mark power-on and major state changes. Review output for credentials, tokens, identifiers, configuration and debug prompts. Link exact observations and their conditions.',expected:'Sensitive values are absent from interfaces accessible to the assessed actor.'},
 {id:'auth',area:'Boottrace',title:'Verify console authentication',why:'A console can expose more privilege than intended.',steps:'Using the access and accounts defined in scope, inspect authentication and session behavior. Record privileges available before and after login. Do not infer authorization from the presence of a login prompt.',expected:'Observed privileges and authentication match the intended access policy.'},
 {id:'secrets',area:'Firmglass',title:'Review firmware for sensitive values',why:'Embedded values require context before they can be called vulnerabilities.',steps:'Record the firmware origin and hash. Review extracted strings and available configuration files. Identify candidate secrets and determine whether they are examples, public material, unique device values or shared credentials. Store sensitive originals carefully and redact report excerpts.',expected:'No confirmed sensitive values are exposed outside their intended trust boundary.'},
 {id:'components',area:'Firmglass',title:'Review software component evidence',why:'Component identification is a starting point for applicability review.',steps:'Import a vendor SBOM or record identified components with their evidence. Validate names and versions. Document applicable advisories, build options, reachability and backported fixes before confirming a vulnerability.',expected:'Candidate matches and verified affected components remain clearly distinguished.'},
 {id:'update',area:'Firmglass',title:'Assess update authenticity and rollback',why:'Updates are a critical trust boundary.',steps:'Review documented update protections and available verification evidence. In an approved recoverable test setup, record observed acceptance and rejection behavior for planned cases. Separately assess integrity, authenticity and rollback policy; a hash alone does not prove signature enforcement.',expected:'Only authorized updates are accepted and rollback behavior follows the stated policy.'},
 {id:'services',area:'Network',title:'Review exposed network services',why:'Exposure depends on device state and network vantage point.',steps:'Import a scan from the scoped environment. Record scanner version, arguments, vantage point and device state. Review each service against intended behavior. Repeat at meaningful lifecycle states.',expected:'Exposed services are necessary, documented and protected for the tested vantage point.'},
 {id:'transport',area:'Network',title:'Verify transport protections',why:'Port numbers and banners do not prove secure transport.',steps:'Review captured protocol exchanges or external test results. Record authentication, certificate validation and encryption observations separately. State which endpoints and traffic paths were actually assessed.',expected:'Sensitive exchanges have effective protection and endpoint validation where required.'},
 {id:'provision',area:'Lifecycle',title:'Compare provisioning and normal operation',why:'Temporary setup behavior can persist unexpectedly.',steps:'Capture the device in a known initial state, during provisioning and after setup. Compare exposed services, console output and account behavior. Record each transition and any temporary credentials or networks.',expected:'Temporary setup access is removed or appropriately protected after provisioning.'},
 {id:'reset',area:'Lifecycle',title:'Verify reset and ownership transfer',why:'A reset may leave credentials or previous-owner data behind.',steps:'Record the reset procedure and recovery plan. In the scoped test environment, compare pre-reset and post-reset identity, configuration and credentials. Verify documented data removal and ownership transfer behavior.',expected:'The observed retained and removed data match the product policy.'},
 {id:'retest',area:'Retest',title:'Verify remediation against the baseline',why:'A firmware change alone does not prove a fix.',steps:'Freeze the prior evidence and conditions. Repeat the original finding procedure on the revised configuration. Link new evidence, compare results and mark resolved only when retest observations support the decision.',expected:'Resolution is supported by a comparable test and explicit evidence.'}
];
